corrected_code:
package repository

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/auth"
	"myapp/models"
)

type TaxFilingRepo struct {
	DB *sqlx.DB
}

func (r *TaxFilingRepo) GetFilingByID(ctx context.Context, filingID int64) (*models.TaxFiling, error) {
	var filing models.TaxFiling
	tenantID := auth.MustGetTenantID(ctx)

	query := "SELECT id, corporate_tax_id, gross_revenue, tax_due, ein FROM tax_filings WHERE id = $1 AND tenant_id = $2"
	if err := r.DB.GetContext(ctx, &filing, query, filingID, tenantID); err != nil {
		return nil, err
	}

	return &filing, nil
}
